architecture.h4_f:
msg = CBOR{v:1, текст, хариулах, илгээсэн_цаг}
ct = AES-GCM-256-Шифрлэх(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {шифр текст: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, текст, хариу бичих үү?, thread_id?, дурдсан?, илгээсэн_at}
ct = AES-GCM-256-Шифрлэх(өрөөний_түлхүүр, үгүй, pt, aad=hex(өрөөний_id))
утас = CBOR{
  v: 1,
  шифрлэгдсэн текст: hex(ct), // хувьсах урт
  үгүй: hex(12 B),
  илгээгч_псевдо: hex(16 B),
  илгээсэн_ат: unix_ms
}

cryptoWire.h5_f:
гадна = CBOR{
  эх_зангилаа: hex32,
  зорилтот_хэрэглэгч: int64,
  дотоод_шифр текст: байт,
  inner_nonce: байт,
  илгээсэн_ат: unix_ms
}
sig = Ed25519-Sign(source_priv, гадна)
POST /холбоо/хүргэх { дугтуй: гадна, сиг: hex64 }

auth.h1_f:
POST /api/баталгаажуулалт/бүртгэл
  { хэрэглэгчийн нэр, нууц үг, x25519_нийтийн_түлхүүр, дэлгэцийн_нэр, утас?, имэйл?, avatar_emoji }

Хариулт 201 Үүсгэсэн:
  { access_token, refresh_token, user_id, хэрэглэгчийн нэр, ...}

auth.h3_f:
access_token ачаалал:
  { sub: user_id, jti: device_id, typ: "хандах", exp: одоо + 15 мин }
refresh_token ачааллыг:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d}

HS256-.env-ээс зангилааны 64 байт нууцаар гарын үсэг зурсан

auth.h4_f:
register_begin(): сорилт = ранд(32)
                    сонголтууд = {rp.id, user.id, pubKeyCredParams, сорилт }
                    буцаах сонголтууд

бүртгүүлэх_төгсгөх(баталгаажуулалт):
  TPM / Secure Enclave root CA-ийн эсрэг баталгаажуулалтыг шалгах
  дэлгүүр {credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/authentication/qr/эхлэх
  → { Үгүй: 128 бит hex, ttl: 60 }
QR ачаалал = { нэг удаа, хэрэглэгчийн_id, сервер: "https://node.example" }

POST /api/authentication/qr/verify { нэг ч удаа биш}
  → шинэ төхөөрөмж бүртгэгдсэн; JWT буцаж ирэв.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(өрөөний_псевдо_давс, илгээгчийн_id)[:16] // 32 hex
шифрлэх текст = AES-GCM-Шифрлэх(өрөөний_түлхүүр, нэг удаа, CBOR_ачаалал, aad=өрөөний_id)

Өргөх хүрээ: { type:"m", өрөө, мессеж:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {файлын нэр, хэмжээ, хэсэг_хэмжээ_санамж}
            ← {байршуулах_id, хэсэг_хэмжээ}
хэсэг PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct байт>
            ← 204
дуусгах POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {файлын_id, url}
TTL дуусаагүй: 24 цаг

files.h4_f:
үгүйсгэх_жагсаалт = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
хэрэв magic.from_buffer(buf[:1024]) in deny_list-д: буцаана 415

calls.h1_f:
POST /api/calls/{room_id}/эхлэх {видео, аудио} → дуудлагын_id
WS нэвтрүүлэг {төрөл:"c", төрөл:"invite", дуудлагын_id}
WS нэвтрүүлэг {төрөл:"c", төрөл:"санал", sdp}
WS нэвтрүүлэг {төрөл:"c", төрөл:"хариулт", sdp}
WS нэвтрүүлэг {төрөл:"c", төрөл:"нэр дэвшигч",мөс} × N
POST /api/calls/{call_id}/end

federation.h2_f:
дугтуй = {
  эх_зангилаа: hex32,
  зорилтот_хэрэглэгч: int64,
  дотоод_шифр текст: байт,
  дотоод_нэг биш: байт,
  илгээсэн_ат: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(дугтуй))
POST /холбоо/хүргэх { дугтуй, тэмдэг }

stealth.h2_f:
ClientHello байт = chrome_120_template нь {
  санамсаргүй = бидний санамсаргүй,
  server_name = манай хостын нэр (эсвэл ECH ороосон),
  session_id = бидний сессийн id,
}
JA4 = t13d_xxxx_xxxx_xxxx (Одоогийн Chrome-ын тогтвортой байдалд таарч байна)

stealth.h4_f:
ЭМГ: POST https://cloudflare-dns.com/dns-query {нэр: x.vortexx.sol}
ECH: ClientHello.extensions += шифрлэгдсэн_sni(HTTPS_бичлэгээс нийтийн_түлхүүр)
DGA: домэйн(t) = суурь32( SHA256(үр ∥ YYYY-MM-DD) )[:16] + ".жишээ"

push.h4_f:
iOS NSE: didReceive(хүсэлт) {шифрийг тайлах(request.content.userInfo)}
Android FCM: onMessageReceived(remoteMessage) {шифрийг тайлах(remoteMessage.data)}
Вэб SW: self.addEventListener('push', e => тайлах(e.data))

controller.h2_f:
хэрэгсэл = тэмдэг_хэрэгсэл
оролт = эх мод, түлхүүрүүд/release.key
манифест = {
  хувилбар: "0.1.0",
  барьсан_: unix_ms,
  файлууд: [{зам, sha256, хэмжээ}, ...]
}
sig = Ed25519-Тэмдэглэгээ(хувилбарын_хувилбар, CBOR(манифест))
гаралт = INTEGRITY.sig.json = {манифест, гарын үсэг зурсан: pub_hex, sig: sig_hex}

bots.h1_f:
үүсгэх: POST /api/bots {хэрэглэгчийн нэр, дэлгэцийн_нэр, код}
          → {bot_id, токен, pubkey}
ажиллуулах: процесст (зангилаа доторх корутин)
      OR гадаад (урт санал асуулга /api/bots/{id}/updates, token-auth'd)
зурвас: {текст, гарын үсэг: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
дээр /эхлэх {
  "Тавтай морил, {ctx.first_name}"
}
дээр / нэмэх <зүйл> {
  state.list = (state.list or []) + [ctx.args.item]
  ялгаруулах "Нэмсэн: {ctx.args.item}"
}

security.h4_f:
canary.txt (өдөр бүр):
  {огноо, тэмдэг: Ed25519-Тэмдэглэгээ(хувилбарын_хуулалт, огноо)}
үйлчлүүлэгч баталгаажуулна → байхгүй эсвэл хүчингүй ⇒ буултыг сэжиглэж байна

яаралтай тусламж:
  админ POST /api/admin/revoke-all {шалтгаан}
  зангилааны дамжуулалт {төрөл:"n", үйл явдал:"буулгалт", шалтгаан}
  Үйлчлүүлэгчид түлхүүрүүдийг арчиж, дахин ачаалахыг албадах

debugging.h2_f:
гистограммыг үнэлэх (маршрут + аргын хувьд):
  vortex_http_requests_total{маршрут,арга,төлөв}
  vortex_http_request_duration_seconds_bucket{маршрут,арга,le}

вэб залгуур хэмжигч:
  vortex_ws_холболтууд{зангилаа}
  vortex_ws_fanout_queue_depth{өрөө, хэрэглэгч}

захиалгат тоолуур:
  vortex_messages_илгээсэн_нийт{өрөөний_төрөл}
  эргүүлэг_дуудлага_эхэлсэн_нийт{төрөл}

