fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  агуулга, -- токенжуулсан багана
  өрөөний дугаар UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
асуулга: SELECT rowid FROM messages_fts WHERE контент MATCH 'foo'

